import{z as i,x as B,o as t,c as n,q as l,j as A,D as o,d as e,s as d,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"路径穿越与上传","description":"","frontmatter":{"title":"路径穿越与上传","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/path-traversal-upload.md","filePath":"cs/path-traversal-upload.md","lastUpdated":1791063341000}'),p={name:"cs/path-traversal-upload.md"};function c(C,a,h,m,D,u){const r=B("Mermaid");return t(),n("div",null,[a[2]||(a[2]=l('<h1 id="路径穿越与上传" tabindex="-1">路径穿越与上传 <a class="header-anchor" href="#路径穿越与上传" aria-label="Permalink to &quot;路径穿越与上传&quot;">​</a></h1><div class="epigraph"><p>文件名若还能携带父目录或未检测的扩展名，存储根就不再是根。上传是同一问题的入口：内容类型与扩展必须由服务器决定，不能信客户端。</p><footer>—— 据 CWE-22；CWE-434；OWASP 文件上传</footer></div><p>上一课<a href="/cs/deserialization-attacks">反序列化</a>让攻击者控制对象图。本课换一个解释器：<strong>文件系统的名字</strong>。讲规范化与根目录约束两条合同，不给读系统文件的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>根路径与用户输入直接拼接、不先规范化，就会逃出根：<code>..</code> 段、多余分隔符、URL 编码都会在内核解析时被合并，最终打开的文件在根外。上传是同一合同的另一半：文件名可带双扩展骗过校验，内容与声明的 MIME 可以完全不一致，落在可执行目录里就等于投放代码。缺口因此是两条：路径规范化之后必须仍在根内；上传文件不可执行。</p><p><span class="marginnote">「规范化」就是把 <code>./</code>、<code>..</code>、重复斜杠、URL 编码这些花写法，按文件系统自己的解析规则化简成唯一的最简形式。直觉：先化简再检查，才保证「你检查的那串字符」和「内核真正打开的那个文件」是同一个名字；顺序反了，检查的是化简前的替身。</span></p><h3 id="符号链接" tabindex="-1">符号链接 <a class="header-anchor" href="#符号链接" aria-label="Permalink to &quot;符号链接&quot;">​</a></h3><p>名字合同的漏洞不止在字符串：根内的符号链接可以指到根外，前缀检查全过、<code>open</code> 却落在别处。策略要么禁止跟随符号链接，要么用 chroot/容器把进程可见的文件系统真切成根。</p><p><span class="marginnote">CWE-22 与 CWE-434。禁止穿越 payload 教程。命令注入下一课是壳解释器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法两步，顺序固定：先按操作系统同样的规则规范化（解析 <code>.</code>、<code>..</code> 与编码），再做根前缀检查——顺序反了检查必被绕过，因为检查的是未解析形式。上传侧：文件名由服务器取随机名，用户名至多作展示；存入不可执行的目录，MIME 与扩展由服务器探测内容决定，不信客户端声明。下一课命令注入。</p>',12)),(t(),A(s,null,{default:o(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAME%5B%22%E7%94%A8%E6%88%B7%E6%96%87%E4%BB%B6%E5%90%8D%22%5D%20--%3E%20NORM%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%0A%20%20NORM%20--%3E%20ROOT%5B%22%E4%BB%8D%E5%9C%A8%E5%AD%98%E5%82%A8%E6%A0%B9%E5%86%85%3F%22%5D%0A%20%20UP%5B%22%E4%B8%8A%E4%BC%A0%22%5D%20--%3E%20EXEC%5B%22%E7%9B%AE%E5%BD%95%E4%B8%8D%E5%8F%AF%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"从仲裁原则看，这是「完整中介」要求：每次访问都要按真实客体名重新评 ACL。路径是客体名，逃出根意味着被检查的名字与被打开的名字不同，ACL 评的是另一个客体，仲裁失效。命令注入是把字符串送进壳解释器——同一形状的问题换了解释器。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},[e("初学者容易以为把输入里的 "),E("code",null,".."),e(" 字符串删掉或黑名单拦截就安全。实际上编码（URL、双重编码）、平台差异、符号链接都能让同一意图变形出现；正解不是枚举坏字符串，而是先按系统规则规范化、再断言「真实路径在根内」这条结构性不变量。")])],-1)),(t(),A(s,null,{default:o(()=>[d(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E6%8B%BC%E6%8E%A5%E5%90%8E%E7%9A%84%E8%B7%AF%E5%BE%84%E4%B8%B2%22%5D%20--%3E%20CHOICE%7B%22%E5%85%88%E5%81%9A%E4%BB%80%E4%B9%88%EF%BC%9F%22%7D%0A%20%20CHOICE%20--%20%22%E6%AD%A3%E7%A1%AE%E9%A1%BA%E5%BA%8F%22%20--%3E%20N1%5B%22%E5%85%88%E6%8C%89%E5%86%85%E6%A0%B8%E5%90%8C%E6%A0%B7%E8%A7%84%E5%88%99%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%0A%20%20N1%20--%3E%20N2%5B%22%E6%96%AD%E8%A8%80%EF%BC%9A%E7%9C%9F%E5%AE%9E%E8%B7%AF%E5%BE%84%E5%9C%A8%E5%AD%98%E5%82%A8%E6%A0%B9%E5%86%85%22%5D%0A%20%20N2%20--%3E%20N3%5B%22%E9%80%9A%E8%BF%87%E6%89%8D%20open%22%5D%0A%20%20CHOICE%20--%20%22%E9%A1%BA%E5%BA%8F%E5%8F%8D%E4%BA%86%22%20--%3E%20W1%5B%22%E5%85%88%E5%AF%B9%E5%8E%9F%E5%A7%8B%E5%AD%97%E7%AC%A6%E4%B8%B2%E5%81%9A%E5%89%8D%E7%BC%80%E6%A3%80%E6%9F%A5%EF%BC%9A%E9%80%9A%E8%BF%87%22%5D%0A%20%20W1%20--%3E%20W2%5B%22%E5%86%85%E6%A0%B8%E8%A7%A3%E6%9E%90%E6%97%B6%E5%90%88%E5%B9%B6%20.%20%E6%AE%B5%22%5D%0A%20%20W2%20--%3E%20W3%5B%22%E5%AE%9E%E9%99%85%E6%89%93%E5%BC%80%E5%9C%A8%E6%A0%B9%E5%A4%96%EF%BC%9A%E6%A3%80%E6%9F%A5%E8%A2%AB%E7%BB%95%E8%BF%87%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>数字实例：存储根取 <code>/data/store</code>，用户输入携带回到上一级的段时，原始字符串以 <code>/data/store</code> 开头、检查通过；按内核规则合并后真实路径变成 <code>/data/secret</code>，前缀断言本应失败——只有先规范化，这个逃逸才在检查里现形。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写穿越 payload 序列，不给绕过实例。命令注入下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对象图之后，文件系统名字是另一个待规范的解释器。</li><li>先规范化、再做根前缀检查；上传存随机名、不可执行。</li><li>内容类型由服务器探测，不信客户端声明。</li><li>下一课命令注入。</li><li>出处：CWE-22；CWE-434；OWASP。</li></ul>',5))])}const F=i(p,[["render",c]]);export{_ as __pageData,F as default};
